import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { toast } from 'react-toastify';
import { useProgress } from '../context/ProgressContext';
import quizService from '../services/quizService';
import videoService from '../services/videoService';
import Spinner from '../components/Spinner';
import { FaCheckCircle, FaTimesCircle } from 'react-icons/fa';
import '../styles/Quiz.css';

const Quiz = () => {
    const { id } = useParams();
    const navigate = useNavigate();
    const { markAsCompleted } = useProgress();

    const [loading, setLoading] = useState(true);
    const [quiz, setQuiz] = useState(null);
    const [video, setVideo] = useState(null);
    const [selectedOption, setSelectedOption] = useState('');
    const [issubmitted, setIsSubmitted] = useState(false);
    const [isCorrect, setIsCorrect] = useState(false);
    const [score, setScore] = useState(null);

    useEffect(() => {
        const fetchQuizData = async () => {
            try {
                setLoading(true);

                // Try to get video first to find associated quiz
                try {
                    const videoData = await videoService.getVideoById(id);
                    setVideo(videoData);

                    // If video has a quiz, use it
                    if (videoData.quiz) {
                        if (typeof videoData.quiz === 'string') {
                            // Quiz is an ID, fetch it
                            const quizData = await quizService.getQuizById(videoData.quiz);
                            setQuiz(quizData);
                        } else {
                            // Quiz is embedded in video
                            setQuiz(videoData.quiz);
                        }
                    }
                } catch (error) {
                    console.log('Video not found, trying quiz directly');
                }

                // If no quiz from video, try fetching quiz by ID
                if (!quiz) {
                    try {
                        const quizData = await quizService.getQuizById(id);
                        setQuiz(quizData);
                    } catch (error) {
                        console.error('Quiz not found');
                    }
                }
            } catch (err) {
                console.error('Error fetching quiz:', err);
                toast.error('Failed to load quiz');
            } finally {
                setLoading(false);
            }
        };

        if (id) {
            fetchQuizData();
        }
    }, [id]);

    const handleSubmit = async () => {
        if (!selectedOption) {
            toast.warning('Please select an answer');
            return;
        }

        setIsSubmitted(true);

        try {
            // Submit quiz response to backend
            const response = await quizService.submitQuizResponse(quiz._id || id, {
                answer: selectedOption,
                videoId: video?._id || id
            });

            if (response.correct || selectedOption === quiz.correctAnswer) {
                setIsCorrect(true);
                setScore(response.score || 100);
                await markAsCompleted(video?._id || id);
                toast.success('Correct! Well done!');
            } else {
                setIsCorrect(false);
                setScore(response.score || 0);
                toast.error('Incorrect. Try again!');
            }
        } catch (error) {
            console.error('Error submitting quiz:', error);
            // Fallback to local validation
            if (selectedOption === quiz.correctAnswer) {
                setIsCorrect(true);
                await markAsCompleted(video?._id || id);
                toast.success('Correct! Well done!');
            } else {
                setIsCorrect(false);
                toast.error('Incorrect. Try again!');
            }
        }
    };

    const handleNext = () => {
        navigate('/student');
    };

    const handleRetry = () => {
        setIsSubmitted(false);
        setSelectedOption('');
        setIsCorrect(false);
        setScore(null);
    };

    if (loading) {
        return <Spinner message="Loading quiz..." />;
    }

    if (!quiz) {
        return (
            <div className="quiz-container">
                <div className="quiz-card">
                    <h2>Quiz not found!</h2>
                    <button onClick={() => navigate('/student')} className="quiz-submit">
                        Back to Dashboard
                    </button>
                </div>
            </div>
        );
    }

    return (
        <div className="quiz-container">
            <div className="quiz-card">
                <h2 className="quiz-title">Quiz{video ? `: ${video.title}` : ''}</h2>
                <p className="quiz-question">{quiz.question || quiz.title}</p>

                <div className="quiz-options">
                    {quiz.options.map((option, index) => (
                        <div
                            key={index}
                            className={`quiz-option ${selectedOption === option ? 'selected' : ''}`}
                            onClick={() => !issubmitted && setSelectedOption(option)}
                        >
                            <input
                                type="radio"
                                name="quiz"
                                value={option}
                                checked={selectedOption === option}
                                onChange={() => !issubmitted && setSelectedOption(option)}
                                disabled={issubmitted}
                                className="quiz-radio"
                            />
                            {option}
                        </div>
                    ))}
                </div>

                {!issubmitted ? (
                    <button
                        className="submit-btn"
                        onClick={handleSubmit}
                        disabled={!selectedOption}
                    >
                        Submit Answer
                    </button>
                ) : (
                    <div className="result-container">
                        {isCorrect ? (
                            <div className="success-text">
                                <FaCheckCircle size={50} color="#006D5B" />
                                <h3>Correct!</h3>
                                <p>You have unlocked the next module.</p>
                                <button className="submit-btn" onClick={handleNext}>Back to Dashboard</button>
                            </div>
                        ) : (
                            <div className="error-text">
                                <FaTimesCircle size={50} color="#ef4444" />
                                <h3>Incorrect</h3>
                                <p>Please try again.</p>
                                <button className="retry-btn" onClick={handleRetry}>Retry</button>
                            </div>
                        )}
                    </div>
                )}
            </div>
        </div>
    );
};

export default Quiz;
